// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { IOrderRecoveryExchange } from "./interfaces/IOrderRecoveryExchange.sol";

/// @notice Permissionless bounded best-effort batches for returning stale order escrow to makers.
contract OrderRecoveryRouter {
    error InvalidAddress();
    error InvalidBatchLength();

    enum ReleaseKind {
        EXPIRED,
        NONCE_INVALIDATED,
        MARKET_CLOSED
    }

    event OrderReleaseAttempt(
        bytes32 indexed orderHash, ReleaseKind indexed kind, bool success, bytes32 failureDataHash
    );

    uint256 public constant MAX_BATCH_LENGTH = 64;
    uint256 public constant MAX_RELEASE_GAS = 300_000;
    uint256 public constant MAX_FAILURE_DATA_BYTES = 256;

    IOrderRecoveryExchange public immutable exchange;

    constructor(
        IOrderRecoveryExchange exchange_
    ) {
        if (address(exchange_) == address(0) || address(exchange_).code.length == 0) {
            revert InvalidAddress();
        }
        exchange = exchange_;
    }

    function releaseExpired(
        bytes32[] calldata orderHashes
    ) external {
        _validateLength(orderHashes.length);
        for (uint256 i; i < orderHashes.length; ++i) {
            _attemptRelease(
                orderHashes[i],
                ReleaseKind.EXPIRED,
                IOrderRecoveryExchange.releaseExpiredOrder.selector
            );
        }
    }

    function releaseInvalidated(
        bytes32[] calldata orderHashes
    ) external {
        _validateLength(orderHashes.length);
        for (uint256 i; i < orderHashes.length; ++i) {
            _attemptRelease(
                orderHashes[i],
                ReleaseKind.NONCE_INVALIDATED,
                IOrderRecoveryExchange.releaseInvalidatedOrder.selector
            );
        }
    }

    function releaseClosedMarkets(
        bytes32[] calldata orderHashes
    ) external {
        _validateLength(orderHashes.length);
        for (uint256 i; i < orderHashes.length; ++i) {
            _attemptRelease(
                orderHashes[i],
                ReleaseKind.MARKET_CLOSED,
                IOrderRecoveryExchange.releaseClosedMarketOrder.selector
            );
        }
    }

    /// @dev Bounds callback gas and return-data copying independently. When failure data is
    ///      truncated the event hashes abi.encode(fullLength, prefix); otherwise it hashes all data.
    ///      A wallet requiring more gas can use the exchange's direct release/cancel entry points.
    function _attemptRelease(
        bytes32 orderHash,
        ReleaseKind kind,
        bytes4 selector
    ) private {
        bytes memory callData = abi.encodeWithSelector(selector, orderHash);
        address target = address(exchange);
        bool success;
        uint256 fullLength;
        bytes memory reason;
        assembly ("memory-safe") {
            success := call(MAX_RELEASE_GAS, target, 0, add(callData, 0x20), mload(callData), 0, 0)
            fullLength := returndatasize()
            let size := fullLength
            if gt(size, MAX_FAILURE_DATA_BYTES) { size := MAX_FAILURE_DATA_BYTES }
            reason := mload(0x40)
            mstore(reason, size)
            returndatacopy(add(reason, 0x20), 0, size)
            mstore(0x40, add(add(reason, 0x20), and(add(size, 0x1f), not(0x1f))))
        }
        bytes32 failureHash = success
            ? bytes32(0)
            : fullLength > MAX_FAILURE_DATA_BYTES
                ? keccak256(abi.encode(fullLength, reason))
                : keccak256(reason);
        emit OrderReleaseAttempt(orderHash, kind, success, failureHash);
    }

    function _validateLength(
        uint256 length
    ) private pure {
        if (length == 0 || length > MAX_BATCH_LENGTH) revert InvalidBatchLength();
    }
}

src/OrderValidator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { IERC1271 } from "@openzeppelin/contracts/interfaces/IERC1271.sol";
import { IERC1155Receiver } from "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { ERC165Checker } from "@openzeppelin/contracts/utils/introspection/ERC165Checker.sol";

import { IOrderValidator } from "./interfaces/IOrderValidator.sol";
import { Order } from "./types/ProtocolTypes.sol";

/// @notice Verifies v2 orders: prices are raw quote / raw base ratios scaled by 1e18.
/// @dev The EIP-712 verifying contract is the exchange, not this stateless helper.
contract OrderValidator is IOrderValidator {
    error InvalidAddress();
    error InvalidSignature();
    error UnsupportedClaimDestination(address destination);

    bytes32 public constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 public constant NAME_HASH = keccak256("ConditionalExchange");
    bytes32 public constant VERSION_HASH = keccak256("2");
    bytes32 public constant ORDER_TYPEHASH = keccak256(
        "Order(address maker,address recipient,bytes32 marketId,uint8 branch,uint8 side,uint8 fundingKind,uint128 quantity,uint128 limitPriceRawX18,uint8 tif,uint64 expiry,uint64 nonce,bytes32 salt)"
    );

    address public immutable override exchange;

    constructor(
        address exchange_
    ) {
        if (exchange_ == address(0) || exchange_.code.length == 0) revert InvalidAddress();
        exchange = exchange_;
    }

    function hashOrder(
        Order calldata order
    ) public view override returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                ORDER_TYPEHASH,
                order.maker,
                order.recipient,
                order.marketId,
                uint8(order.branch),
                uint8(order.side),
                uint8(order.fundingKind),
                order.quantity,
                order.limitPriceRawX18,
                uint8(order.tif),
                order.expiry,
                order.nonce,
                order.salt
            )
        );
        bytes32 domainSeparator = keccak256(
            abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, exchange)
        );
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
    }

    function validate(
        Order calldata order,
        bytes calldata signature
    ) external view override returns (bytes32 orderHash) {
        // Both makers can receive inactive claims, price improvement, or cancelled claim escrow.
        // ERC-165 detects incompatibility only at open time; matchers must still simulate fills.
        _requireClaimDestination(order.maker);
        if (order.recipient != order.maker) _requireClaimDestination(order.recipient);
        orderHash = hashOrder(order);
        if (order.maker.code.length == 0) {
            (address recovered, ECDSA.RecoverError error,) = ECDSA.tryRecover(orderHash, signature);
            if (error != ECDSA.RecoverError.NoError || recovered != order.maker) {
                revert InvalidSignature();
            }
        } else {
            (bool success, bytes memory result) = order.maker
                .staticcall(abi.encodeCall(IERC1271.isValidSignature, (orderHash, signature)));
            if (
                !success || result.length < 32
                    || abi.decode(result, (bytes32)) != bytes32(IERC1271.isValidSignature.selector)
            ) revert InvalidSignature();
        }
    }

    function _requireClaimDestination(
        address destination
    ) private view {
        if (
            destination.code.length != 0
                && !ERC165Checker.supportsInterface(destination, type(IERC1155Receiver).interfaceId)
        ) revert UnsupportedClaimDestination(destination);
    }
}

src/PositionRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import { IConditionalTokens } from "./interfaces/IConditionalTokens.sol";
import { ProtocolConstants } from "./libraries/ProtocolConstants.sol";
import { ExpectedCtfReceiver } from "./utils/ExpectedCtfReceiver.sol";

/// @notice Noncustodial exact-amount helpers for CTF merge and redemption.
/// @dev Users may always bypass this helper and call Conditional Tokens directly.
contract PositionRouter is ExpectedCtfReceiver, ReentrancyGuard {
    using SafeERC20 for IERC20;

    error InvalidAmount();
    error InvalidRecipient();
    error InvalidPositionSet();
    error ResidualBalance();

    event PositionsMerged(
        address indexed account,
        address indexed recipient,
        address indexed collateralToken,
        bytes32 conditionId,
        uint256 amount
    );
    event PositionsRedeemed(
        address indexed account,
        address indexed recipient,
        address indexed collateralToken,
        bytes32 conditionId,
        uint256 payout
    );

    constructor(
        IConditionalTokens conditionalTokens_
    ) ExpectedCtfReceiver(conditionalTokens_) { }

    function mergeForUser(
        IERC20 collateralToken,
        bytes32 conditionId,
        uint256 amount,
        address recipient
    ) external nonReentrant returns (uint256 collateralReturned) {
        if (amount == 0) revert InvalidAmount();
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();

        (uint256[] memory indexSets, uint256[] memory positionIds) =
            _binaryPositionIds(collateralToken, conditionId);
        uint256[] memory amounts = new uint256[](2);
        amounts[0] = amount;
        amounts[1] = amount;
        _requireNoPositionBalance(positionIds);

        _expectBatch(address(this), msg.sender, positionIds, amounts);
        conditionalTokens.safeBatchTransferFrom(msg.sender, address(this), positionIds, amounts, "");
        _assertExpectedTransferReceived();

        uint256 beforeBalance = collateralToken.balanceOf(address(this));
        conditionalTokens.mergePositions(
            collateralToken, ProtocolConstants.PARENT_COLLECTION_ID, conditionId, indexSets, amount
        );
        collateralReturned = collateralToken.balanceOf(address(this)) - beforeBalance;
        if (collateralReturned != amount) revert ResidualBalance();
        collateralToken.safeTransfer(recipient, collateralReturned);

        _requireNoPositionBalance(positionIds);
        emit PositionsMerged(
            msg.sender, recipient, address(collateralToken), conditionId, collateralReturned
        );
    }

    function redeemForUser(
        IERC20 collateralToken,
        bytes32 conditionId,
        uint256[] calldata indexSets,
        uint256[] calldata amounts,
        address recipient
    ) external nonReentrant returns (uint256 payout) {
        uint256 length = indexSets.length;
        if (length == 0 || length > 2 || length != amounts.length) revert InvalidPositionSet();
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();

        uint256[] memory positionIds = new uint256[](length);
        uint256[] memory copiedIndexSets = new uint256[](length);
        uint256[] memory copiedAmounts = new uint256[](length);
        uint256 seen;
        for (uint256 i; i < length; ++i) {
            uint256 indexSet = indexSets[i];
            if (
                (indexSet != ProtocolConstants.YES_INDEX_SET
                        && indexSet != ProtocolConstants.NO_INDEX_SET) || amounts[i] == 0
                    || (seen & indexSet) != 0
            ) revert InvalidPositionSet();
            seen |= indexSet;
            copiedIndexSets[i] = indexSet;
            copiedAmounts[i] = amounts[i];
            positionIds[i] = _positionId(collateralToken, conditionId, indexSet);
        }
        _requireNoPositionBalance(positionIds);

        _expectBatch(address(this), msg.sender, positionIds, copiedAmounts);
        conditionalTokens.safeBatchTransferFrom(
            msg.sender, address(this), positionIds, copiedAmounts, ""
        );
        _assertExpectedTransferReceived();

        uint256 beforeBalance = collateralToken.balanceOf(address(this));
        conditionalTokens.redeemPositions(
            collateralToken, ProtocolConstants.PARENT_COLLECTION_ID, conditionId, copiedIndexSets
        );
        payout = collateralToken.balanceOf(address(this)) - beforeBalance;
        if (payout != 0) collateralToken.safeTransfer(recipient, payout);

        _requireNoPositionBalance(positionIds);
        emit PositionsRedeemed(msg.sender, recipient, address(collateralToken), conditionId, payout);
    }

    function _binaryPositionIds(
        IERC20 collateralToken,
        bytes32 conditionId
    ) private view returns (uint256[] memory indexSets, uint256[] memory positionIds) {
        indexSets = new uint256[](2);
        indexSets[0] = ProtocolConstants.YES_INDEX_SET;
        indexSets[1] = ProtocolConstants.NO_INDEX_SET;
        positionIds = new uint256[](2);
        positionIds[0] = _positionId(collateralToken, conditionId, indexSets[0]);
        positionIds[1] = _positionId(collateralToken, conditionId, indexSets[1]);
    }

    function _positionId(
        IERC20 collateralToken,
        bytes32 conditionId,
        uint256 indexSet
    ) private view returns (uint256) {
        bytes32 collectionId = conditionalTokens.getCollectionId(
            ProtocolConstants.PARENT_COLLECTION_ID, conditionId, indexSet
        );
        return conditionalTokens.getPositionId(collateralToken, collectionId);
    }

    function _requireNoPositionBalance(
        uint256[] memory positionIds
    ) private view {
        uint256 length = positionIds.length;
        for (uint256 i; i < length; ++i) {
            if (conditionalTokens.balanceOf(address(this), positionIds[i]) != 0) {
                revert ResidualBalance();
            }
        }
    }
}

