src/interfaces/IConditionalTokens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { IERC1155 } from "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IConditionalTokens is IERC1155 {
    function payoutNumerators(
        bytes32 conditionId,
        uint256 index
    ) external view returns (uint256);

    function payoutDenominator(
        bytes32 conditionId
    ) external view returns (uint256);

    function prepareCondition(
        address oracle,
        bytes32 questionId,
        uint256 outcomeSlotCount
    ) external;

    function reportPayouts(
        bytes32 questionId,
        uint256[] calldata payouts
    ) external;

    function splitPosition(
        IERC20 collateralToken,
        bytes32 parentCollectionId,
        bytes32 conditionId,
        uint256[] calldata partition,
        uint256 amount
    ) external;

    function mergePositions(
        IERC20 collateralToken,
        bytes32 parentCollectionId,
        bytes32 conditionId,
        uint256[] calldata partition,
        uint256 amount
    ) external;

    function redeemPositions(
        IERC20 collateralToken,
        bytes32 parentCollectionId,
        bytes32 conditionId,
        uint256[] calldata indexSets
    ) external;

    function getOutcomeSlotCount(
        bytes32 conditionId
    ) external view returns (uint256);

    function getConditionId(
        address oracle,
        bytes32 questionId,
        uint256 outcomeSlotCount
    ) external pure returns (bytes32);

    function getCollectionId(
        bytes32 parentCollectionId,
        bytes32 conditionId,
        uint256 indexSet
    ) external view returns (bytes32);

    function getPositionId(
        IERC20 collateralToken,
        bytes32 collectionId
    ) external pure returns (uint256);
}

src/interfaces/IIOCExchange.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import { Order } from "../types/ProtocolTypes.sol";
import { IProtocolAuthority } from "./IProtocolAuthority.sol";

interface IIOCExchange {
    function authority() external view returns (IProtocolAuthority);
    function openIOCOrder(
        Order calldata order,
        bytes calldata signature
    ) external returns (bytes32 orderHash);
    function matchIOCOrders(
        Order calldata takerOrder,
        Order calldata makerOrder,
        uint128 fillQuantity
    ) external;
    function cancelIOCRemainder(
